window.RP_SESSION={"id":"S-8c8481f8d8ca","messages":[{"id":"RP-III-0114782","time":"2026-06-16T11:20:00+09:00","room":"RP III","name":"언데드와 대화하는 인물(이름 미상)","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"달그락 달그락.\n\n\"아니, 그래서 죽었다구요?\"\n\n달그락 달그락.\n\n\"허, 진짜 머리 깨져 있네. 징그러우니까 치우쇼.\n\n그나저나, 그래서 이제 뭐 하겠다는 겁니까? 보니까 말도 못 하는 것 같은데.\"\n\n달그락 달그락.\n\n\"...돌아가시려구요? 허 참, 벙어리에 흑마술 쓰는 언데드를 받아주진 않을 것 같은데.\n\n...아니, 벙어리인 게 차라리 나으려나.\"","characters":[]},{"id":"RP-III-0114783","time":"2026-06-16T11:25:00+09:00","room":"RP III","name":"언데드와 대화하는 인물(이름 미상)","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그래서 죽어보니 어땠어요? 그분께서 두 발 벗고 마중이라도 나오셨습니까?\"\n\n달그락 달그락.\n\n\"여전하시구만.\"","characters":[]},{"id":"RP-III-0114784","time":"2026-06-16T11:38:00+09:00","room":"RP III","name":"언데드와 대화하는 인물(이름 미상)","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0114785","time":"2026-06-16T11:38:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
